static double qpc(){LARGE_INTEGER x,f;QueryPerformanceCounter(&x);QueryPerformanceFrequency(&f);return (double)x.QuadPart/(double)f.QuadPart;}
static uint32_t expected(uint32_t index,uint32_t seed,uint32_t iters){uint32_t v=index^seed;for(uint32_t i=0;i<iters;++i){v^=v>>13;v*=0x85ebca6b;v^=v<<7;v+=(i^index)*0xc2b2ae35;}return v;}
